import{_ as a,O as n,H as r,f as o,i as s,k as i,b as u}from"./chunks/framework.Ch3ZxHbh.js";const b=JSON.parse('{"title":"Culinary consumption patterns before, during and after the lockdown","description":"","frontmatter":{},"headers":[],"relativePath":"blog/culinary.md","filePath":"blog/culinary.md"}'),c={name:"blog/culinary.md"};function d(l,e,h,p,m,f){const t=n("SeriesChart");return r(),o("div",null,[e[0]||(e[0]=s('<h1 id="culinary-consumption-patterns-before-during-and-after-the-lockdown" tabindex="-1">Culinary consumption patterns before, during and after the lockdown <a class="header-anchor" href="#culinary-consumption-patterns-before-during-and-after-the-lockdown" aria-label="Permalink to &quot;Culinary consumption patterns before, during and after the lockdown&quot;">​</a></h1><div class="byline"><span class="byline-author">Alexander Götz</span><span class="byline-date">3 September 2020</span></div><p>On 27 August 2020 the State Secretariat for Economic Affairs (SECO) announced a historic 8.2% quarter-on-quarter decline in Swiss economic output in the second quarter of 2020. In its <a href="https://www.seco.admin.ch/dam/seco/de/dokumente/Wirtschaft/Wirtschaftslage/VIP%20Quartalssch%C3%A4tzungen/konjunkturnotiz_2020_08_27.pdf.download.pdf/konjunkturnotiz_2020_08_27.pdf" target="_blank" rel="noreferrer">economic note</a>, SECO explained that private consumption in particular had suffered an unprecedented slump. Because private consumption is the largest GDP component, its swings hit output especially hard, so its decline was a major driver of the GDP fall.</p><p>Ever since the outbreak, <a href="https://www.nber.org/papers/w26949" target="_blank" rel="noreferrer">US economists</a> had speculated that consumption habits might change not just in the short term but in the medium or long term, with online shopping for everyday goods getting a particular boost. Whether the make-up of the consumer basket really changes is another question, best examined by looking at specific categories. Here we look at one of the most everyday categories: food.</p><p>We chose the terms <em>Restaurant</em> and <em>Bar</em>, along with <em>Rezept</em> (recipe) and <em>Sauerteig</em> (sourdough). The first pair reflects going out. During the lockdown both were hardly searched, returning to their usual level only around June 2020. Interestingly, <em>Restaurant</em> was searched even more after the lockdown than before, perhaps a compensatory effect, perhaps uncertainty about whether a place was open. <em>Rezept</em> and <em>Sauerteig</em> stand for cooking at home: the lockdown turned restaurant-goers into cooks, and sourdough saw a huge hype between March and May that ended abruptly once restrictions eased.</p>',5)),i(t,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_3.csv",ids:["Restaurant","Bar","Rezept","Sauerteig"],from:"2020-01-01",eventset:"reopening",title:"Eating out vs cooking at home",subtitle:"2020; dashed lines mark Swiss reopening phases"}),e[1]||(e[1]=u("p",null,"By late summer the terms had returned to old levels. Whether private consumption could stabilise output in the coming quarter remained open, though we were skeptical that sourdough would be part of that future.",-1))])}const w=a(c,[["render",d]]);export{b as __pageData,w as default};
